    name: "kvhttp",
    platforms: [.macOS(.v15)],
    products: [.executable(name: "app", targets: ["app"])],
    targets: [
        .target(name: "KVServer", swiftSettings: [.enableUpcomingFeature("ExistentialAny")]),
