import Foundation

/// A parsed HTTP/1.x request.
public struct HTTPRequest: Sendable, Equatable {
    public var method: String
    public var target: String
    public var minorVersion: Int
    public var headers: [(name: String, value: String)]
    public var body: Data

    public init(method: String, target: String, minorVersion: Int = 1, headers: [(name: String, value: String)] = [], body: Data = Data()) {
        self.method = method
        self.target = target
        self.minorVersion = minorVersion
        self.headers = headers
        self.body = body
    }

    /// The request target without any query string or fragment.
    public var path: Substring {
        target.prefix { $0 != "?" && $0 != "#" }
    }

    /// First value of the header `name` (case-insensitive).
    public func header(_ name: String) -> String? {
        headers.first { $0.name.caseInsensitiveCompare(name) == .orderedSame }?.value
    }

    /// Whether the client wants the connection kept open after this request.
    public var keepAlive: Bool {
        let tokens = (header("Connection") ?? "")
            .split(separator: ",")
            .map { $0.trimmingCharacters(in: .whitespaces).lowercased() }
        if tokens.contains("close") { return false }
        return minorVersion >= 1 || tokens.contains("keep-alive")
    }

    public static func == (lhs: Self, rhs: Self) -> Bool {
        lhs.method == rhs.method && lhs.target == rhs.target && lhs.minorVersion == rhs.minorVersion
            && lhs.body == rhs.body && lhs.headers.elementsEqual(rhs.headers) { $0 == $1 }
    }
}

/// An HTTP response ready to be serialized.
public struct HTTPResponse: Sendable {
    public var status: Int
    public var headers: [(name: String, value: String)]
    public var body: Data

    public init(status: Int, headers: [(name: String, value: String)] = [], body: Data = Data()) {
        self.status = status
        self.headers = headers
        self.body = body
    }

    /// Wire representation. `Content-Length` and `Connection` are always set by this method.
    public func serialized(keepAlive: Bool) -> Data {
        var head = "HTTP/1.1 \(status) \(Self.reasonPhrase(status))\r\n"
        for (name, value) in headers {
            head += "\(name): \(value)\r\n"
        }
        head += "Content-Length: \(body.count)\r\n"
        head += "Connection: \(keepAlive ? "keep-alive" : "close")\r\n\r\n"
        var data = Data(head.utf8)
        data.append(body)
        return data
    }

    static func reasonPhrase(_ status: Int) -> String {
        switch status {
        case 200: "OK"
        case 201: "Created"
        case 204: "No Content"
        case 400: "Bad Request"
        case 404: "Not Found"
        case 405: "Method Not Allowed"
        case 408: "Request Timeout"
        case 411: "Length Required"
        case 413: "Content Too Large"
        case 431: "Request Header Fields Too Large"
        case 500: "Internal Server Error"
        case 501: "Not Implemented"
        case 505: "HTTP Version Not Supported"
        default: "Unknown"
        }
    }
}

import Foundation
import Synchronization

/// Thread-safe in-memory key-value store.
public final class KVStore: Sendable {
    private let storage = Mutex<[String: Data]>([:])

    public init() {}

    /// Stores `value` under `key`. Returns `true` if the key was newly created.
    @discardableResult
    public func put(_ key: String, _ value: Data) -> Bool {
        storage.withLock { $0.updateValue(value, forKey: key) == nil }
    }

    public func get(_ key: String) -> Data? {
        storage.withLock { $0[key] }
    }

    /// Removes `key`. Returns `true` if it was present.
    @discardableResult
    public func delete(_ key: String) -> Bool {
        storage.withLock { $0.removeValue(forKey: key) != nil }
    }

    /// All keys, sorted ascending.
    public func keys() -> [String] {
        storage.withLock { Array($0.keys) }.sorted()
    }
}

import Foundation

/// Reasons a byte stream cannot be parsed as HTTP/1.x requests.
public enum HTTPParseError: Error, Equatable {
    case malformed
    case headersTooLarge
    case bodyTooLarge
    case unsupportedTransferEncoding
    case unsupportedVersion

    /// The status code to answer with before closing the connection.
    public var status: Int {
        switch self {
        case .malformed: 400
        case .headersTooLarge: 431
        case .bodyTooLarge: 413
        case .unsupportedTransferEncoding: 501
        case .unsupportedVersion: 505
        }
    }
}

/// Incremental HTTP/1.x request parser: feed bytes with `append`, pull requests with `next`.
public struct RequestParser: Sendable {
    public static let defaultMaxHeaderBytes = 16 * 1024

    private struct Head {
        var request: HTTPRequest
        var bodyStart: Int
        var contentLength: Int
    }

    private let maxHeaderBytes: Int
    private let maxBodyBytes: Int
    private var buffer: [UInt8] = []
    private var pending: Head?
    /// Where to resume searching for the end of the header block.
    private var scanOffset = 0

    public init(maxHeaderBytes: Int = defaultMaxHeaderBytes, maxBodyBytes: Int) {
        self.maxHeaderBytes = maxHeaderBytes
        self.maxBodyBytes = maxBodyBytes
    }

    /// Whether any unconsumed bytes are buffered.
    public var hasBufferedBytes: Bool { !buffer.isEmpty }

    public mutating func append(_ bytes: some Sequence<UInt8>) {
        buffer.append(contentsOf: bytes)
    }

    /// Returns the next complete request, or `nil` if more bytes are needed.
    public mutating func next() throws(HTTPParseError) -> HTTPRequest? {
        if pending == nil {
            guard let headerEnd = findHeaderEnd() else {
                if buffer.count > maxHeaderBytes { throw .headersTooLarge }
                return nil
            }
            guard headerEnd <= maxHeaderBytes else { throw .headersTooLarge }
            pending = try parseHead(buffer[..<headerEnd], bodyStart: headerEnd + 4)
        }
        guard let head = pending else { return nil }
        let end = head.bodyStart + head.contentLength
        guard buffer.count >= end else { return nil }

        var request = head.request
        request.body = Data(buffer[head.bodyStart..<end])
        buffer.removeSubrange(..<end)
        pending = nil
        scanOffset = 0
        return request
    }

    private mutating func findHeaderEnd() -> Int? {
        let terminator: [UInt8] = [13, 10, 13, 10]
        guard buffer.count >= 4 else { return nil }
        var index = scanOffset
        while index + 4 <= buffer.count {
            if buffer[index] == 13, buffer[index..<(index + 4)].elementsEqual(terminator) {
                return index
            }
            index += 1
        }
        scanOffset = max(0, buffer.count - 3)
        return nil
    }

    private func parseHead(_ bytes: ArraySlice<UInt8>, bodyStart: Int) throws(HTTPParseError) -> Head {
        guard let text = String(validating: bytes, as: UTF8.self) ?? String(bytes: bytes, encoding: .isoLatin1) else {
            throw .malformed
        }
        var lines = text.split(separator: "\r\n", omittingEmptySubsequences: false)[...]
        // Tolerate leading empty lines between requests (RFC 9112 §2.2).
        while lines.first?.isEmpty == true { lines.removeFirst() }
        guard let requestLine = lines.popFirst() else { throw .malformed }

        let parts = requestLine.split(separator: " ", omittingEmptySubsequences: false)
        guard parts.count == 3, !parts[0].isEmpty, !parts[1].isEmpty,
              parts[0].allSatisfy(\.isHTTPTokenCharacter) else { throw .malformed }
        let minorVersion: Int
        switch parts[2] {
        case "HTTP/1.1": minorVersion = 1
        case "HTTP/1.0": minorVersion = 0
        default:
            throw parts[2].hasPrefix("HTTP/") ? .unsupportedVersion : .malformed
        }

        var headers: [(name: String, value: String)] = []
        for line in lines {
            guard let colon = line.firstIndex(of: ":") else { throw .malformed }
            let name = line[..<colon]
            guard !name.isEmpty, name.allSatisfy(\.isHTTPTokenCharacter) else { throw .malformed }
            let value = line[line.index(after: colon)...].trimmingCharacters(in: .whitespaces)
            headers.append((String(name), value))
        }

        let request = HTTPRequest(method: String(parts[0]), target: String(parts[1]), minorVersion: minorVersion, headers: headers)
        if let encoding = request.header("Transfer-Encoding"), encoding.lowercased() != "identity" {
            throw .unsupportedTransferEncoding
        }
        let lengths = headers.filter { $0.name.caseInsensitiveCompare("Content-Length") == .orderedSame }.map(\.value)
        var contentLength = 0
        if let first = lengths.first {
            guard lengths.allSatisfy({ $0 == first }), !first.isEmpty, first.utf8.allSatisfy({ (48...57).contains($0) }) else {
                throw .malformed
            }
            guard first.count <= 18, let length = Int(first) else { throw .bodyTooLarge }
            contentLength = length
        }
        guard contentLength <= maxBodyBytes else { throw .bodyTooLarge }
        return Head(request: request, bodyStart: bodyStart, contentLength: contentLength)
    }
}

private extension Character {
    /// `tchar` from RFC 9110 §5.6.2.
    var isHTTPTokenCharacter: Bool {
        guard let ascii = asciiValue, ascii > 32, ascii < 127 else { return false }
        return !"\"(),/:;<=>?@[\\]{}".contains(self)
    }
}

import Foundation

/// Maps requests onto the key-value store. Independent of networking so it can be unit tested.
public struct Router: Sendable {
    /// Largest accepted value, in bytes.
    public static let maxValueSize = 1 << 20
    static let maxKeyLength = 64
    private static let keyPrefix = "/kv/"

    private let store: KVStore

    public init(store: KVStore) {
        self.store = store
    }

    public func handle(_ request: HTTPRequest) -> HTTPResponse {
        let path = request.path
        let method = request.method
        if path == "/health" {
            guard method == "GET" else { return Self.methodNotAllowed(allow: "GET") }
            return HTTPResponse(status: 200, headers: [("Content-Type", "text/plain; charset=utf-8")], body: Data("ok".utf8))
        }
        if path == "/kv" {
            guard method == "GET" else { return Self.methodNotAllowed(allow: "GET") }
            return listKeys()
        }
        guard path.hasPrefix(Self.keyPrefix) else {
            return HTTPResponse(status: 404)
        }
        let key = path.dropFirst(Self.keyPrefix.count)
        guard Self.isValidKey(key) else {
            return HTTPResponse(status: 400)
        }
        let name = String(key)
        switch method {
        case "GET":
            guard let value = store.get(name) else { return HTTPResponse(status: 404) }
            return HTTPResponse(status: 200, headers: [("Content-Type", "application/octet-stream")], body: value)
        case "PUT":
            guard request.body.count <= Self.maxValueSize else { return HTTPResponse(status: 413) }
            return HTTPResponse(status: store.put(name, request.body) ? 201 : 200)
        case "DELETE":
            return HTTPResponse(status: store.delete(name) ? 204 : 404)
        default:
            return Self.methodNotAllowed(allow: "GET, PUT, DELETE")
        }
    }

    /// A key matches `[A-Za-z0-9_-]{1,64}`.
    static func isValidKey(_ key: some StringProtocol) -> Bool {
        let bytes = key.utf8
        guard (1...maxKeyLength).contains(bytes.count) else { return false }
        return bytes.allSatisfy { byte in
            switch byte {
            case UInt8(ascii: "A")...UInt8(ascii: "Z"),
                 UInt8(ascii: "a")...UInt8(ascii: "z"),
                 UInt8(ascii: "0")...UInt8(ascii: "9"),
                 UInt8(ascii: "_"), UInt8(ascii: "-"):
                true
            default:
                false
            }
        }
    }

    private func listKeys() -> HTTPResponse {
        // Valid keys contain only [A-Za-z0-9_-], so they need no JSON escaping.
        let json = "[" + store.keys().map { "\"\($0)\"" }.joined(separator: ",") + "]"
        return HTTPResponse(status: 200, headers: [("Content-Type", "application/json")], body: Data(json.utf8))
    }

    private static func methodNotAllowed(allow: String) -> HTTPResponse {
        HTTPResponse(status: 405, headers: [("Allow", allow)])
    }
}

import Foundation
import Network

/// HTTP/1.1 key-value server built on Network.framework.
public struct Server: Sendable {
    public let host: String
    public let port: UInt16
    /// Connections idle for longer than this are closed.
    public var idleTimeout: Duration = .seconds(30)

    private let router: Router

    public init(host: String = "127.0.0.1", port: UInt16, store: KVStore = KVStore()) {
        self.host = host
        self.port = port
        self.router = Router(store: store)
    }

    /// Listens and serves connections until the listener fails or the task is cancelled.
    public func run() async throws {
        guard let nwPort = NWEndpoint.Port(rawValue: port) else { throw ServerError.invalidPort(port) }
        let parameters = NWParameters.tcp
        parameters.allowLocalEndpointReuse = true
        parameters.requiredLocalEndpoint = .hostPort(host: NWEndpoint.Host(host), port: nwPort)
        if let tcp = parameters.defaultProtocolStack.transportProtocol as? NWProtocolTCP.Options {
            tcp.noDelay = true
        }

        let listener = try NWListener(using: parameters)
        let queue = DispatchQueue(label: "kvhttp.network", attributes: .concurrent)
        let (connections, continuation) = AsyncThrowingStream.makeStream(of: NWConnection.self)
        listener.newConnectionHandler = { continuation.yield($0) }
        listener.stateUpdateHandler = { state in
            switch state {
            case .failed(let error): continuation.finish(throwing: error)
            case .cancelled: continuation.finish()
            default: break
            }
        }
        continuation.onTermination = { _ in listener.cancel() }
        listener.start(queue: queue)

        let router = self.router
        let idleTimeout = self.idleTimeout
        try await withThrowingDiscardingTaskGroup { group in
            for try await connection in connections {
                group.addTask {
                    await HTTPConnection(connection: connection, router: router, idleTimeout: idleTimeout)
                        .serve(on: queue)
                }
            }
        }
    }
}

public enum ServerError: Error, CustomStringConvertible {
    case invalidPort(UInt16)

    public var description: String {
        switch self {
        case .invalidPort(let port): "invalid port \(port)"
        }
    }
}

/// Serves HTTP requests on one accepted connection.
private struct HTTPConnection {
    private static let receiveChunkSize = 64 * 1024

    let connection: NWConnection
    let router: Router
    let idleTimeout: Duration

    func serve(on queue: DispatchQueue) async {
        connection.start(queue: queue)
        defer { connection.cancel() }

        var parser = RequestParser(maxBodyBytes: Router.maxValueSize)
        do {
            while true {
                let request: HTTPRequest
                do {
                    guard let next = try await nextRequest(&parser) else { return }
                    request = next
                } catch let error as HTTPParseError {
                    let response = HTTPResponse(status: error.status)
                    try await send(response.serialized(keepAlive: false))
                    return
                }
                let keepAlive = request.keepAlive
                try await send(router.handle(request).serialized(keepAlive: keepAlive))
                guard keepAlive else { return }
            }
        } catch {
            // The peer went away or timed out; the deferred cancel releases the connection.
        }
    }

    /// Reads until a full request is parsed. Returns `nil` on a clean end of stream between requests.
    private func nextRequest(_ parser: inout RequestParser) async throws -> HTTPRequest? {
        while true {
            if let request = try parser.next() { return request }
            let (data, isComplete) = try await receive()
            if let data { parser.append(data) }
            if isComplete {
                if let request = try parser.next() { return request }
                if parser.hasBufferedBytes { throw HTTPParseError.malformed }
                return nil
            }
        }
    }

    private func receive() async throws -> (Data?, Bool) {
        let connection = self.connection
        let watchdog = Task {
            try await Task.sleep(for: idleTimeout)
            connection.cancel()
        }
        defer { watchdog.cancel() }
        return try await withCheckedThrowingContinuation { continuation in
            connection.receive(minimumIncompleteLength: 1, maximumLength: Self.receiveChunkSize) { data, _, isComplete, error in
                if let error {
                    continuation.resume(throwing: error)
                } else {
                    continuation.resume(returning: (data, isComplete))
                }
            }
        }
    }

    private func send(_ data: Data) async throws {
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, any Error>) in
            connection.send(content: data, isComplete: false, completion: .contentProcessed { error in
                if let error {
                    continuation.resume(throwing: error)
                } else {
                    continuation.resume()
                }
            })
        }
    }
}

import Foundation
import KVServer

let arguments = CommandLine.arguments
guard arguments.count == 2, let port = UInt16(arguments[1]), port != 0 else {
    FileHandle.standardError.write(Data("usage: \(arguments.first ?? "app") <port>\n".utf8))
    exit(2)
}

do {
    try await Server(port: port).run()
} catch {
    FileHandle.standardError.write(Data("error: \(error)\n".utf8))
    exit(1)
}

import Foundation
import Testing
@testable import KVServer

@Suite struct RouterTests {
    let router = Router(store: KVStore())

    private func send(_ method: String, _ path: String, _ body: String = "") -> HTTPResponse {
        router.handle(HTTPRequest(method: method, target: path, body: Data(body.utf8)))
    }

    @Test func health() {
        let response = send("GET", "/health")
        #expect(response.status == 200)
        #expect(response.body == Data("ok".utf8))
        #expect(send("POST", "/health").status == 405)
    }

    @Test func crud() {
        #expect(send("PUT", "/kv/a", "x").status == 201)
        #expect(send("PUT", "/kv/a", "y").status == 200)
        #expect(send("GET", "/kv/a").body == Data("y".utf8))
        #expect(send("DELETE", "/kv/a").status == 204)
        #expect(send("DELETE", "/kv/a").status == 404)
        #expect(send("GET", "/kv/a").status == 404)
    }

    @Test func listIsSortedJSON() {
        for key in ["b", "A", "a", "_"] { _ = send("PUT", "/kv/\(key)") }
        let response = send("GET", "/kv")
        #expect(response.body == Data(#"["A","_","a","b"]"#.utf8))
        #expect(response.headers.contains { $0 == ("Content-Type", "application/json") })
    }

    @Test(arguments: ["/kv/", "/kv/a/b", "/kv/bad.key", "/kv/" + String(repeating: "k", count: 65), "/kv/%41", "/kv/é"])
    func invalidKeys(path: String) {
        #expect(send("GET", path).status == 400)
    }

    @Test func otherErrors() {
        #expect(send("GET", "/nope").status == 404)
        #expect(send("PATCH", "/kv/a").status == 405)
        #expect(send("POST", "/kv").status == 405)
        #expect(send("GET", "/kv/" + String(repeating: "k", count: 64)).status == 404)
    }
}

@Suite struct RequestParserTests {
    @Test func parsesPipelinedRequestsAcrossChunks() throws {
        var parser = RequestParser(maxBodyBytes: 1024)
        let wire = "PUT /kv/a HTTP/1.1\r\nContent-Length: 5\r\n\r\nhelloGET /health HTTP/1.1\r\nConnection: close\r\n\r\n"
        for byte in wire.utf8 { parser.append([byte]) }
        let first = try #require(try parser.next())
        #expect(first.method == "PUT" && first.target == "/kv/a" && first.body == Data("hello".utf8))
        #expect(first.keepAlive)
        let second = try #require(try parser.next())
        #expect(second.target == "/health" && !second.keepAlive)
        #expect(try parser.next() == nil)
    }

    @Test func rejectsOversizedBody() {
        var parser = RequestParser(maxBodyBytes: 4)
        parser.append(Array("PUT /kv/a HTTP/1.1\r\nContent-Length: 5\r\n\r\n".utf8))
        #expect(throws: HTTPParseError.bodyTooLarge) { try parser.next() }
    }

    @Test(arguments: ["garbage\r\n\r\n", "GET /\r\n\r\n", "GET / HTTP/1.1\r\nbad header\r\n\r\n", "GET / HTTP/1.1\r\nContent-Length: -1\r\n\r\n"])
    func rejectsMalformed(wire: String) {
        var parser = RequestParser(maxBodyBytes: 4)
        parser.append(Array(wire.utf8))
        #expect(throws: HTTPParseError.malformed) { try parser.next() }
    }
}
